"""Built-in architectures (lazy references; see ``enerzyme.models.presets``).

Entries point at the factory that builds each Core. As a family moves onto
``ComposableCore`` its ``core`` reference switches to the preset function.
"""

from . import ArchitectureSpec, add_architecture


def _add(name, core, build, layers, aliases=(), losses=None, family=""):
    add_architecture(ArchitectureSpec(name=name, core=core, build_params=build, layer_params=layers,
                                      losses=losses, aliases=tuple(aliases), family=family))


_add('schnet', '.presets.scalar:schnet', '.schnet:DEFAULT_BUILD_PARAMS', '.schnet:DEFAULT_LAYER_PARAMS', family='scalar')
